            crate::types::keyspace_options_for(KeyspaceProfile::Hot)
        })?;
        let emergency_deny = database.keyspace(KEYSPACE_EMERGENCY_DENY, || {
            crate::types::keyspace_options_for(KeyspaceProfile::Hot)
        })?;
        let artifact_acceptance = database.keyspace(KEYSPACE_ARTIFACT_ACCEPTANCE, || {
