        let _process_lock = ProcessLock::acquire(path_ref)?;
        Ok(Self {
            database,
            workflow_source,
            compiled_ir,
            run_header,
            run_inputs,
            events,
            run_snapshot,
            blob,
            index_status,
            index_workflow,
            index_action,
            emergency_deny,
            artifact_acceptance,
