            fail_next_persist: AtomicBool::new(false),
            #[cfg(test)]
            fail_next_compiled_ir_readback: AtomicBool::new(false),
            #[cfg(test)]
            fail_next_batch_commit: AtomicBool::new(false),
            write_lock: Mutex::new(()),
            _process_lock,
        })
    }

